// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An obstetric patient's risk assessment at her visit or during her admission. */
export interface AssessmentIn {
  patient_id: number;
  admission_id?: number | null;
  ticket_id?: number | null;
  gestation_weeks?: number | null;
  /** Asked on purpose, never pre-filled */
  high_risk: boolean;
  /** From GET /maternity/high-risk-conditions (active names); at least one when high_risk */
  conditions?: string[];
  condition_note?: string | null;
  /** The patient (and her family) told of the risk and counselled (II C p166) */
  counselled: boolean;
  /** Required when high_risk: what was said */
  counselling_note?: string | null;
  plan: "CareHere" | "Refer";
  /** The external referral, when referred */
  referral_id?: number | null;
  /** Required for a high-risk patient in Category I (indicator 28) */
  nutrition_assessment?: string | null;
  /** Corrective measures and follow-up advice */
  nutrition_advice?: string | null;
  follow_up?: string | null;
}

export interface ObstetricAssessmentOut {
  assessment_id: number;
  patient_id: number;
  mrn: string;
  patient_name: string;
  admission_id: number | null;
  admission_number: string | null;
  ticket_id: number | null;
  ticket_number: string | null;
  gestation_weeks: number | null;
  high_risk: boolean;
  conditions: string[];
  condition_note: string | null;
  counselled: boolean;
  counselling_note: string | null;
  plan: "CareHere" | "Refer";
  referral_id: number | null;
  referral_number: string | null;
  nutrition_assessment: string | null;
  nutrition_advice: string | null;
  follow_up: string | null;
  assessed_by: number;
  author_stamp: AuthorStampOut;
  assessed_at: string;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface ObstetricConditionOut {
  condition_id: number;
  name: string;
  /** Null: not decided yet */
  provision: "Managed" | "Referred" | null;
  referral_note: string | null;
  /** One of the twelve examples of the PHC manuals (II C p165) */
  from_manual: boolean;
  is_active: boolean;
  sort_order: number;
  row_version: number;
}

/** An outpatient's or emergency patient's referral to another facility (the clinic manual, indicator 29). */
export interface ReferralIn {
  /** The OPD visit */
  ticket_id?: number | null;
  /** The emergency visit */
  er_visit_id?: number | null;
  /** The consultation note (not an inpatient's: use the admission's transfer or referral slip) */
  encounter_id?: number | null;
  /** The facility from the contact list (GET /mlc/contacts) */
  destination_contact_id?: number | null;
  /** Default: the contact's name; the facility the patient chooses when they ask to go */
  destination_name?: string | null;
  destination_department?: string | null;
  reason: string;
  urgency: "Routine" | "Urgent" | "Emergency";
  /** Symptoms, findings and the provisional diagnosis for the receiving doctor */
  clinical_summary: string;
  treatment_given?: string | null;
  /** The patient asked to go elsewhere (the note says so) */
  at_patient_request?: boolean;
  /** WithStaff: the establishment's staff take the patient; the receiving facility's acknowledgement is then recorded (POST /referrals/{id}/acknowledge) */
  transport: "Own" | "Ambulance" | "Rescue" | "WithStaff";
  /** Required for WithStaff: who goes with the patient */
  escort_name?: string | null;
  /** Oxygen, a drip, monitoring on the way */
  care_during_transfer?: string | null;
}

export interface ReferralOut {
  referral_id: number;
  referral_number: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  father_or_husband_name: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  address: string | null;
  mobile: string | null;
  ticket_id: number | null;
  er_visit_id: number | null;
  encounter_id: number | null;
  referred_by: number;
  referred_by_name: string;
  referred_by_stamp: AuthorStampOut;
  destination_contact_id: number | null;
  destination_name: string;
  destination_department: string | null;
  reason: string;
  urgency: "Routine" | "Urgent" | "Emergency";
  clinical_summary: string;
  treatment_given: string | null;
  at_patient_request: boolean;
  transport: "Own" | "Ambulance" | "Rescue" | "WithStaff";
  escort_name: string | null;
  care_during_transfer: string | null;
  status: "Issued" | "Acknowledged" | "Cancelled";
  acknowledged_by_name: string | null;
  acknowledged_at: string | null;
  acknowledgement_note: string | null;
  cancel_reason: string | null;
  cancelled_at: string | null;
  created_at: string;
  row_version: number;
  /** Our staff took the patient and the receiving facility's acknowledgement is not recorded yet */
  acknowledgement_pending: boolean;
}

export interface EstablishmentOut {
  /** Name it as expected_revision when applying a change */
  revision: number;
  /** Null until the first profile is recorded */
  profile: CurrentProfileOut | null;
  /** The capabilities whose new work may start now */
  active: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** The rules that follow the PHC category, never a service: show them on their screens instead of learning them from errors (audit H-7) */
  rules_in_force: RuleInForceOut[];
  capabilities: CapabilityOut[];
  /** What each service-bound workspace and screen shows now. Apply it after login and again on establishment.changed; never decide it from the profile's category */
  views: ViewsOut;
}

export interface CurrentProfileOut {
  code: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  label: string;
  establishment: "Clinic" | "Hospital";
  /** The PHC's band, in words */
  beds: string;
  /** The MSDS framework (GET /msds/indicators?category=) */
  framework: string;
  framework_edition: string;
  indicators: number;
  registration_number: string;
  effective_from: string;
  /** The beds the licence names; null when none was entered */
  licensed_beds: number | null;
  confirmed_at: string;
  confirmed_by_name: string;
}

export interface RuleInForceOut {
  code: string;
  description: string;
  /** Whether it applies to this establishment's current profile */
  applies: boolean;
  /** The PHC categories it applies to */
  profiles: string[];
  /** What the server answers when the rule is not met */
  error_code: string;
  operations: string[];
  /** The screens that should say it before the server refuses */
  screens: string[];
  /** Where it is enforced (for the backend team) */
  source: string;
}

export interface CapabilityOut {
  capability: "dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes";
  label: string;
  purpose: string;
  /** Available (never switched on), Preparing (set up, no new work), Active, Retiring (no new work, open work continues), Retired (records only) */
  state: "Available" | "Preparing" | "Active" | "Retiring" | "Retired";
  state_since: string;
  changed_by_name: string | null;
  requires: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** Never Active under the Clinic profile */
  hospital_only: boolean;
  /** False: not in this release; it cannot be switched on */
  implemented: boolean;
  /** What the database refuses while it is not Active */
  new_work: string | null;
  /** The operations that start its new work: hide them unless it is Active (the API refuses them anyway: CAPABILITY_INACTIVE). Every other operation, reads and the steps of started work included, stays */
  operations: GateOut[];
  /** Its open work, while Active or Retiring */
  outstanding: OutstandingOut[];
  /** The services declared to the PHC (GET /phc/services) that name it; a declaration is what the PHC is told, never proof the service runs */
  phc_declared: string[];
  /** Where the declaration and this service disagree: declared but not running, or running but not declared. Advice only */
  declaration_note: string | null;
}

export interface GateOut {
  /** METHOD /path: it starts new work of this service (OpenAPI x-capability-gates) */
  operation: string;
  /** Only the requests it names (hide or disable that choice, not the whole action); null: every request */
  when: string | null;
  /** True: work started before the service began retiring continues while it is Retiring (show it then too) */
  continues_while_retiring: boolean;
}

export interface OutstandingOut {
  /** admissions, inpatient_bills, emergency_visits, operations, recovery_stays, lab_tests, imaging_orders, critical_results, prescriptions_to_dispense, stock_on_hand, drug_recalls, sterile_packs, programme_enrolments, procedure_notes */
  kind: string;
  count: number;
  /** What it is, in words */
  label: string;
  /** How it ends: completed, transferred or settled (it is never stranded) */
  how: string;
  /** The operations that end it, as METHOD /path; all stay allowed while the service is Retiring */
  operations: string[];
}

export interface ViewsOut {
  /** The workspaces that exist for a service; any other is core */
  workspaces: WorkspaceViewOut[];
  /** The screens that exist for a service (or sit in such a workspace); any other screen is core and always full */
  screens: ScreenViewOut[];
}

export interface WorkspaceViewOut {
  /** A workspace that exists for these services (GET /meta/workspaces) */
  workspace: string;
  /** Any one of them gives it its view */
  services: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** full or open_work: in the launcher (open_work with the banner 'No new ... from now on'); records: in the launcher marked 'Records'; hidden: not in the launcher */
  view: "full" | "open_work" | "records" | "setup" | "hidden";
}

export interface ScreenViewOut {
  /** The screen catalogue's id (GET /meta/screens, the MCP server's get_screen) */
  screen_id: string;
  workspace: string;
  /** Any one of them gives it its view */
  services: ("dispensing" | "outsourced_diagnostics" | "laboratory" | "imaging" | "outpatient_procedures" | "inpatient" | "emergency_department" | "surgery" | "cssd" | "blood_transfusion" | "blood_center" | "maternity" | "home_visits" | "preventive_programmes")[];
  /** Daily work, the setup a service needs before it is switched on, or its registers and statistics */
  role: "work" | "setup" | "records";
  /** full: show it; open_work: show it without new work of the service and with the banner; records: history, prints and corrections only; setup: only from Facility settings; hidden: in no menu */
  view: "full" | "open_work" | "records" | "setup" | "hidden";
}

export interface MlcContactOut {
  contact_id: number;
  contact_type: "PoliceStation" | "MlrHospital" | "ReferralHospital" | "HealthOffice" | "TraumaCentre" | "BloodBank" | "RescueService" | "FireBrigade" | "PoliceEmergency" | "Ambulance" | "SocialService";
  name: string;
  district: string | null;
  phone: string | null;
  alt_phone: string | null;
  address: string | null;
  notes: string | null;
  is_active: boolean;
}

/** Record an obstetric risk assessment — POST /api/v1/maternity/assessments (who may call: holders of maternity.record). */
export function assessMaternityAssessments(body: AssessmentIn): Promise<ObstetricAssessmentOut> {
  return api<ObstetricAssessmentOut>("POST", `/maternity/assessments`, body, { idempotent: true });
}

/** Obstetric assessments of a patient or a period — GET /api/v1/maternity/assessments (who may call: holders of maternity.view). */
export function assessments(query?: { patient_id?: number | null; date_from?: string | null; date_to?: string | null; high_risk_only?: boolean; limit?: number; before_id?: number | null }): Promise<ObstetricAssessmentOut[]> {
  return api<ObstetricAssessmentOut[]>("GET", withQuery(`/maternity/assessments`, query), undefined);
}

/** The hospital's high-risk obstetric cases — GET /api/v1/maternity/high-risk-conditions (who may call: holders of maternity.policy.manage or maternity.view or msds.view). */
export function listConditions(query?: { include_inactive?: boolean }): Promise<ObstetricConditionOut[]> {
  return api<ObstetricConditionOut[]>("GET", withQuery(`/maternity/high-risk-conditions`, query), undefined);
}

/** Refer an outpatient or emergency patient to another facility — POST /api/v1/referrals (who may call: holders of referral.create). */
export function createReferrals(body: ReferralIn): Promise<ReferralOut> {
  return api<ReferralOut>("POST", `/referrals`, body, { idempotent: true });
}

/** The establishment's profile and services, with the configuration revision — GET /api/v1/establishment (who may call: any logged-in user). */
export function getEstablishment(): Promise<EstablishmentOut> {
  return api<EstablishmentOut>("GET", `/establishment`, undefined);
}

/** Police stations and MLR hospitals (contact list) — GET /api/v1/mlc/contacts (who may call: holders of mlc.case.manage or mlc.register.view or mlc.setup.manage). */
export function contacts(query?: { contact_type?: "PoliceStation" | "MlrHospital" | "ReferralHospital" | "HealthOffice" | "TraumaCentre" | "BloodBank" | "RescueService" | "FireBrigade" | "PoliceEmergency" | "Ambulance" | "SocialService" | null; include_inactive?: boolean }): Promise<MlcContactOut[]> {
  return api<MlcContactOut[]>("GET", withQuery(`/mlc/contacts`, query), undefined);
}
